import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import './Home.css';
import { getQuestions } from '../../services/api';

function Home() {
  const [questions, setQuestions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const email = localStorage.getItem('email');
  const isLoggedIn = !!localStorage.getItem('token');

  useEffect(() => {
    getQuestions()
      .then(data => {
        setQuestions(data);
        setLoading(false);
      })
      .catch(err => {
        setError('Eroare la încărcarea întrebărilor');
        setLoading(false);
      });
  }, []);

  return (
    <div className="home-page">
      <main className="main-content">
        {isLoggedIn && email ? (
          <>
            <h2>Bine ai revenit, <span className="highlight">{email}</span>!</h2>
            <p>Poți vedea sau adăuga întrebări în comunitatea noastră.</p>
            <div style={{ margin: '30px 0' }}>
              <Link to="/questions/new" className="btn special">Pune o întrebare</Link>
            </div>
          </>
        ) : (
          <>
            <h2>Bine ai venit!</h2>
            <p>Alătură-te comunității noastre și participă la discuții interesante!</p>
            <div className="main-buttons">
              <Link to="/login" className="btn">Login</Link>
              <Link to="/register" className="btn">Register</Link>
              <Link to="/questions" className="btn special">Vezi întrebările</Link>
            </div>
          </>
        )}

        <section className="forum-section">
          <h3 style={{ marginBottom: 20 }}>Întrebări recente</h3>
          {loading ? (
            <p>Se încarcă întrebările...</p>
          ) : error ? (
            <p style={{ color: 'red' }}>{error}</p>
          ) : questions.length === 0 ? (
            <p>Nu există întrebări momentan.</p>
          ) : (
            <div className="question-list-home">
              {questions.slice(0, 8).map(q => (
                <div key={q.id} className="question-card">
                  <h4>{q.title}</h4>
                  <p className="question-meta">Autor: <b>{q.user.username}</b></p>
                  <div className="question-tags">
                    {q.questionTags.map(tag => (
                      <span className="tag" key={tag.id}>{tag.tag.name}</span>
                    ))}
                  </div>
                  <Link to={`/questions/${q.id}`} className="see-question-link">Vezi detalii</Link>
                </div>
              ))}
            </div>
          )}
          <div style={{ marginTop: 30 }}>
            <Link to="/questions" className="btn special">Vezi toate întrebările</Link>
          </div>
        </section>
      </main>
      <footer className="footer">
        <p>&copy; 2025 Forum App. Toate drepturile rezervate.</p>
      </footer>
    </div>
  );
}

export default Home;
